<script setup lang="ts">
import {onMounted,ref} from 'vue';import type {RequestFn} from './media';import {date} from './lib';
const props=defineProps<{request:RequestFn}>();const rows=ref<Record<string,any>[]>([]),scopes=ref<Record<string,string>>({}),editing=ref<Record<string,any>|null>(null),busy=ref(false),error=ref(''),notice=ref('');
async function load(){const d=await props.request('admin/administrators');rows.value=d.items;scopes.value=d.scopes}
function edit(row?:Record<string,any>){error.value='';editing.value=row?{id:row.id,version:row.admin_version,email:row.email,name:row.name,password:'',password_confirm:'',enabled:row.status==='active',scopes:[...row.admin_scopes]}:{email:'',name:'',password:'',password_confirm:'',enabled:true,scopes:['support']}}
async function save(){const e=editing.value;if(!e)return;busy.value=true;error.value='';try{if(e.password!==e.password_confirm)throw new Error('两次输入的密码不一致');await props.request('admin/administrators',e.id?'PUT':'POST',e);editing.value=null;await load();notice.value='副管理员已保存；权限变更会注销其已有登录会话。'}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
onMounted(()=>load().catch(e=>error.value=String(e)));
</script>
<template><div v-if="error" class="alert error">{{error}}</div><div v-if="notice" class="alert">{{notice}}</div><div class="section-head"><p class="muted">主管理员保留站点密钥、版本更新与管理员管理；副管理员仅可使用勾选的功能。</p><button class="primary" @click="edit()">＋ 添加副管理员</button></div><section class="panel"><div v-for="r in rows" :key="r.id" class="list-row"><div><strong>{{r.name}} <span class="badge">{{r.is_owner?'主管理员':'副管理员'}}</span></strong><small>{{r.email}}</small><small>{{r.is_owner?'全部权限':r.admin_scopes.map((s:string)=>scopes[s]||s).join('、')}}</small><small>创建于 {{date(r.created_at)}}</small></div><span class="badge">{{r.status==='active'?'已启用':'已停用'}}</span><button v-if="!r.is_owner" @click="edit(r)">编辑权限</button></div></section><div v-if="editing" class="modal-backdrop" @click.self="editing=null"><form class="modal" role="dialog" aria-modal="true" aria-label="副管理员设置" @submit.prevent="save"><div class="section-head"><h2>{{editing.id?'编辑副管理员':'添加副管理员'}}</h2><button type="button" @click="editing=null" aria-label="关闭">×</button></div><div v-if="error" class="alert error">{{error}}</div><div class="fields"><label>名称<input v-model="editing.name" required maxlength="80"></label><label>登录邮箱<input v-model="editing.email" type="email" required :readonly="!!editing.id"></label><label>{{editing.id?'重设密码（留空保持）':'初始密码'}}<input v-model="editing.password" type="password" :required="!editing.id" minlength="12" maxlength="256" autocomplete="new-password"></label><label>再次输入密码<input v-model="editing.password_confirm" type="password" :required="!!editing.password" minlength="12" maxlength="256" autocomplete="new-password"></label></div><p v-if="editing.password_confirm&&editing.password!==editing.password_confirm" class="alert error">两次输入的密码不一致</p><h3>可操作功能</h3><div class="fields"><label v-for="(name,id) in scopes" :key="id" class="multi"><input type="checkbox" v-model="editing.scopes" :value="id">{{name}}</label></div><label class="multi"><input type="checkbox" v-model="editing.enabled">允许登录</label><div class="modal-actions"><button type="button" @click="editing=null">取消</button><button class="primary" :disabled="busy||!editing.scopes.length||editing.password!==editing.password_confirm">保存</button></div></form></div></template>
